//
//   블록 스키마 (코스·사전 공통):
//     { title, where, lead, why: [], shot: { cap, rows: [] }, dos: [], says: [{ in, out }], warns: [], never: [], neverTitle }
//       shot = 화면 그림 (2.27~ · HelpShot.jsx 가 그린다). 검수사 지시 «기능별로 화면 추가 하는 방향으로»
//       where = 화면 어디인지 (📍),  dos = 하는 순서,  says = 실제 입력 → 앱 답변,  warns = 막히는 조건
//   ⚠ 여기 적힌 입력 예시는 전부 파서(nlSearch.js)에 실제로 구현된 것만 적는다. 안 되는 건 warns에 적는다.

