      '**«본선 작업중 · 접속 검수원 없음»(4.05)** — 앱에 접속한 검수원이 없어도 터미널(동방·PCTC)이 그 배를 작업 중으로 알리면(작업시작일시가 지난 배만) «대기 중» 대신 이렇게 보입니다. 양하·선적 막대 바로 아래에 청록색 막대와 함께 **«본선 작업현황 완료 n/전체 (p%) · 잔여 m»** 이 한 줄로 나옵니다(4.05-01 — 검수사 «진행상황을 안보임 … 터미널별 본선작업현황에 있는 갯수라도 표기»). 폰의 접힌 줄에는 «본선 n/전체 (p%)» 한 줄로 나오고 «자세히» 를 열면 막대가 나옵니다. 검수원이 접속해 있어도 이 막대는 참고로 함께 보입니다. 이 숫자는 터미널 본선 작업 현황(호기 합계)이 말하는 것이고, 오른쪽 «남음» 아래의 «본선 잔여» 도 같습니다. 검수원이 앱에서 누른 완료(앞의 완료 n/N)와는 별개이며 다를 수 있습니다 — 터미널 컨별 실적은 받지 않으므로(검수사 지시 2026-10-03) 앱의 완료·남음 계산은 그대로입니다(검수사 2026-10-05 «1개 단위로 실시간으로 맞추긴 힘듭니다. 하지만 어느정도는 맞아야 한다고 생각합니다»).',
