      '작업이 끝나 갈 때(선적 잔여 20개 이하) 뜨는 🚢 출항 배지의 시각은 **⚓도선 예보가 먼저이고, 없으면 🚢PORT-MIS 신고 출항**이다. 두 곳 말고 다른 자료는 쓰지 않는다(3.53-13).',
