      '[＋ 새 항차 ▾] → [📋 물량 예보 붙여넣기]로 카톡 물량 예보를 붙여넣을 때, 그 항차에 선적칸이 없으면 원문 항차번호로 **선적칸을 같이 만든다**(1.42~). 만들기 전에 창 아래에 «→ {선박} 항차에 선적칸({항차번호})을 만들고 저장합니다» 같은 안내가 뜬다.',
