      '카톡에서 복사할 때 `[이름] [시각]`이 같이 붙어도 그대로 붙여넣으면 된다(1.43~). 종전에는 그 머리말 때문에 **첫 줄이 통째로 안 읽혀** FULL 수량이 빠졌다.',
      '항차번호가 안 적힌 예보(연태훼리 등)는 **담당자 이름과 날짜로 배를 찾아준다**(1.43~). 이럴 때는 보라색 `🔍 추정` 배지가 뜬다 — **배와 양하/선적이 맞는지 눈으로 확인하고 저장한다.** 틀리면 저장하지 말고 항차번호를 적어 다시 붙여넣는다.',
