      '카드의 항차 삭제는 보관소를 안 거친다 — 확인 단계에 지워질 완료 기록 수가 나온다(3.60-09). 3.60-19~ 지우기 전에 그 항차를 **휴지통(archive_trash)에 그대로 복사**하고 확인된 뒤에만 지운다 — 복사가 안 되면 지우지 않는다. 복원은 아직 화면이 없어 클로드에게 말하면 된다.',
