      '선적: [트윈] 탭 → 앞 컨 끝 4자리 입력 → 짝 추천 → [트윈 한 번에 선적확인 (두 대)]. 플랜상 짝이면 [✅ 지정 자리 그대로 트윈 선적확인]이 먼저 나온다.',
