      '멈출 때: [⏸ 양하 중단] → 사유 칩(장비 고장·강풍 대기·안개 대기·우천 대기·화물 이상·점심 식사) 중 하나 → [⏸ 중단 보고]. 다시 시작하면 [▶ 재개]. 진행 중 작업 카드에도 [양하 중단 / 양하 재개 / 양하 완료] 단추가 있다.',
