          '규격 표기는 선사에 제출하는 형식이다(1.99~) — 하이큐브 리퍼는 40RH, 표준높이 리퍼는 40RF. 리스트·필터 칩·카고플랜 별첨·검수 리스트 전부 같은 표기. 검수 리스트 규격 칸만 3.60-15~ 세관 신고 유형이 먼저다 — 나머지 서류는 선박별 마감 텔리 기준 그대로.',
