          '  **RZOR(카페리)는 카고플랜 단추가 덱플랜을 엽니다(4.04)** — 양하는 선사 STOWAGE PLAN 그림, 선적은 마감텔리 그림입니다. 위 도구줄은 [● 컬러 / ◐ 흑백] [🖨 인쇄] [📄 PDF] [📊 Excel] — Excel 도 양하는 선사 덱플랜, 선적은 마감텔리 양식으로 내려받습니다. 특수화물(DG·RF·FR·OT·TK)은 **컬러에서만 칸 바탕색**, 흑백은 색 없이 글자(카고플랜과 같은 단추·같은 저장)이고 **★ X-RAY 는 두 쪽 다 빨강**입니다. LUG 는 보라(흑백은 굵은) 테두리, D덱 LOLO 구역은 **굵은 선으로 구역 전체**를 둘러 대수를 적습니다. 서명란(Chief Checker·Chief Officer — 선적은 줄 아래에 검수원 이름이 더해집니다)은 출력·PDF·Excel 에만 있고 앱 화면에는 없습니다. 양하·선적 덱플랜 모두 덱마다 서명줄 위에 사인할 자리(약 14mm)가 비어 있습니다 — 칸 그림이 서명줄 바로 위까지 내려오지 않습니다(선적은 4.04-04 부터이고 칸 높이가 약간 낮아집니다). **Excel 은 파일 안에 인쇄 설정(가로 A4)이 들어 있어** 엑셀에서 열어 바로 인쇄해도 덱 한 장이 한 쪽에 나옵니다 — 양하는 «한 쪽에 맞춤»(선사 덱플랜과 같음), 선적은 마감텔리 양식처럼 덱 블록 사이에서 쪽을 나누고 가로 한 쪽에 들어가는 배율(최대 60%)로 찍습니다.',
          '  칸 읽는 법 — **양하는 풀에만 색을 칠하고 엠티는 안 칠합니다**(2.38~). 글자는 모두 검정입니다. **선적은 다릅니다** — 칸 색은 «목적지» 하나만 뜻합니다(3.7~). 3.39부터 칠한 칸은 풀, 흰 칸에 목적지색 테두리만 둘러진 칸은 엠티입니다. 가운데 글자는 종류이고, DG·FR·OT·TK 엠티는 글자 뒤에 E가 붙습니다(DGE·FRE·OTE·TKE).',
          '  **글자는 전부 진한 검정입니다**(2.38-01~). 양하에서는 칠한 칸이 풀, 안 칠한 칸이 엠티이고 일반 풀은 하늘색, 특수화물은 제 색(DG 연빨강·리퍼 연청록·FR 연초록·OT 연보라·TK 연주황)으로 칠합니다 — 별첨2 범례와 같은 색입니다. 선적에서는 그 칠을 안 합니다(바탕은 목적지 색이라 자리를 다투므로) — 그래서 선적 별첨2 도 색 없이 글자만 나옵니다.',
          '  풀이냐는 **리스트**로 봅니다. DG·TK·FR·OT·리퍼 풀은 제 글자를 달고 있어도 리스트가 풀이면 칠합니다 — 글자만 보고 엠티로 읽히면 안 되니까요.',
          '  **선적은 목적지(POD)마다 바탕색이 다릅니다**(3.7) — 선적 위치를 잡을 때 포트가 칸에서 바로 보이게. 종전 무늬(빗금·줄·점)는 없앴습니다 — 검수사 «눈이 아프고 구분이 잘 안됩니다». **색은 목적지마다 정해져 있습니다** — 대수 순으로 돌려 쓰지 않으니 «이 색이면 어디»가 항상 같습니다(대련은 늘 연초록, 연태는 늘 연파랑, 일조는 늘 연분홍). 평택에서 실은 230항차 선적 EDI 를 세어 **실제로 나가는 목적지 31곳 전부**에 색을 못 박았습니다 — 새 항로가 생기면 그때만 색 없이 글자로 나옵니다. **칸 오른쪽 위에 목적지 글자**(1~3자, 칸 크기에 맞춰 정해짐)가 작게 붙고, **화물 표기는 왼쪽으로 비켜섭니다**(3.27) — 종전에는 표기자가 가운데라 목적지 글자와 붙어 한 덩어리로 읽혔습니다. 두 글자 표기(DG·RF 같은 것)는 그 칸만 조금 작아지고, ◆시프팅·▲긴급 표식이 있는 칸은 그 표식과 겹치지 않게 종전 가운데 그대로입니다 — 다만 칸이 너무 좁은 배는 목적지 글자를 못 담으므로 그때는 색과 별첨1로만 읽습니다(그 사실은 플랜 바닥글에 «이 배는 칸이 좁아 목적지 글자를 안 적는다»로 적힙니다). 가운데 글자는 종전대로 종류(F·e·E·RF·DG·FR·OT·TK)라서 **특수화물도 목적지 바탕색을 그대로 깔고 종류는 글자가 말합니다**. 600dpi 흑백 레이저에서 같은 플랜에 나오는 목적지끼리 회색 농도가 안 겹치도록 잡았습니다(실측 0쌍). 베이플랜 화면과 카고플랜이 같은 색을 쓰고, 목적지 글자는 카고플랜에만 있습니다. 베이 상세는 흰 바탕입니다(3.69-03). 별첨1 POD 표는 **포트명 칸 자체에 그 색이 깔립니다**. **별첨은 한곳에 모으되 넘치면 옆 빈 칸을 씁니다**(3.27) — 넘칠 때는 별첨1·2 를 한 칸에, 별첨3 을 두 번째 칸 위쪽에 놓습니다. 그러면 글자가 잘리지 않고 오히려 커집니다.',
          '  **X는 옆 짝수 베이 40피트가 차지한 홀수 베이 자리** 표시입니다. 그 자리에 실린 화물이 아니라서 40피트가 풀이어도 칠하지 않습니다. 그 40피트 본체는 아래 페어 칸 (04)05 쪽에 나옵니다.',
          '  글자 — F=풀 · e=20피트 엠티 · E=40/45피트 엠티 · DG=위험물 · TK=탱크 · RF·RE=리퍼 풀·엠티(그림은 슬래시 없이 두 글자, 리스트·서류는 R/F·R/E 그대로) · FR=플랫랙 · OT=오픈탑/OOG. 회색 칸은 평택에서 안 내리는 통과화물입니다.',
          '  색이 뜻하는 것 — 양하는 칠한 칸이 풀(일반은 하늘색, 특수화물은 제 색)이고 선사는 별첨1의 ■ 색으로 알려 줍니다. 선적은 목적지(POD)별입니다. **선적에는 선사색을 안 씁니다**(2.38~) — 그래서 선적 별첨2도 선사별에서 화물 종류별로 바뀌었습니다.',
          '  **베이플랜에서 하늘색 테두리 칸은 «자리를 내주고 옮겨 온 컨»입니다**(3.13). 실린 컨이 남의 계획 자리에 앉으면 밀려난 계획 컨은 그 컨이 비운 자리로 자동으로 옮겨 보입니다 — 겹침·빈칸 없이 남은 컨 번호가 다 보이게. 규격·풀엠티·항구가 다른데 옮겨 왔으면 칸 테두리가 주황색으로 바뀝니다. 실린 판정은 종전대로 완료(초록)뿐입니다.',
          '  **선사 목록(CLL)에 남의 짐이 섞여 와도 선적분으로 안 셉니다**(3.14) — EDI 가 «남의 항구에서 실려 남의 항구로 간다»고 말하고 자리까지 준 컨은 통과화물입니다. 실측 DJCF 0151S 24대가 평택 작업이 없는 베이(5·7·10·17·19·25·27)에 떠 있던 것이 그것입니다. 리스트에만 있는 컨(엠티 목록 등)은 종전대로 선적분으로 삽니다.',
          '  **예상EDI(부킹) 배는 자리와 컨넘버를 두 번 세지 않습니다**(3.26) — 선사가 컨번호 없이 자리만 준 EDI(예상EDI)에 실번호 리스트가 다 들어오면 목록·검수 리스트·VGM 은 실번호로, 별첨1·2·3 은 자리(계획)로 한 번만 셉니다. 검증 박스에는 «부킹 자리 316 · 실번호 리스트 316 — 자리를 실번호가 다 채웠습니다»로 뜹니다(«리스트에 없음 316 / EDI에 없음 316» 경고가 아닙니다).',
          '🚢 베이 상세 — 슬롯 단위 위치표(현장용). 흰 바탕(3.69-03)이고, 앱 화면 위 미리보기에서 [🖨 인쇄] · [📄 PDF] · [📊 엑셀]로 내보냅니다.',
          '  **고정 칸 모양의 칸 안 글씨는 칸 크기에 맞춰 크기가 정해집니다**(3.69-04) — 칸이 큰 배는 크게, 좁은 배는 작게(6pt 아래로는 안 내려갑니다). 고정 칸 모양이 아닌 배는 종전 크기(8.5 / 7.2 / 6.3pt)를 씁니다. 다섯 줄은 칸 한가운데에 같은 왼쪽 선으로 맞춰 적힙니다. 칸 크기는 그대로입니다.',
          '⚖ VGM 리스트 — 선적일 때만 나옵니다. 평택 선적분 컨별 VGM(kg)을 영문으로 뽑아 본선이 요청할 때 냅니다(새 창 — 단추가 없으니 Ctrl+P).',
          'FINAL WORKING REPORT — 허브 아래쪽 카드에서 양하/선적 항차와 BERTH를 넣고 [📄 결제용](완료 가정) 또는 [📄 작업용](진행 현황). 새 창에서 [🖨 프린터 인쇄] · [📄 PDF 저장] · [📊 엑셀 다운로드]를 씁니다.',
